// Calcular KPIs da semana atual (seg-sex)
const agora = new Date();
const seg = new Date(agora);
seg.setDate(agora.getDate() - agora.getDay() + (agora.getDay()===0 ? -6 : 1));
seg.setHours(0,0,0,0);

const emSemana = (dataStr) => {
  if (!dataStr) return false;
  const d = new Date(dataStr);
  return d >= seg && d <= agora;
};

const viagens = ($('Ler Viagens').all() || []).map(i=>i.json).filter(v=>emSemana(v.data_saida));
const abasts  = ($('Ler Abastecimentos').all() || []).map(i=>i.json).filter(v=>emSemana(v.data));
const manuts  = ($('Ler Manutenções').all() || []).map(i=>i.json).filter(v=>emSemana(v.data));
const quebras = ($('Ler Quebras').all() || []).map(i=>i.json).filter(v=>emSemana(v.data));

const soma = (arr, campo) => arr.reduce((s,x)=>s+(parseFloat(x[campo])||0),0);
const totalCarga  = soma(viagens, 'valor_carga');
const totalCusto  = soma(viagens, 'custo_viagem');
const totalManut  = soma(manuts, 'valor');
const totalAbast  = soma(abasts, 'valor_total');
const m2Exp       = soma(quebras, 'm2_expedido');
const m2Qbr       = soma(quebras, 'm2_quebrado');

const pctRota   = totalCarga>0 ? (totalCusto/totalCarga*100).toFixed(2) : null;
const pctQuebra = m2Exp>0 ? (m2Qbr/m2Exp*100).toFixed(2) : null;
const pctManut  = totalCarga>0 ? (totalManut/totalCarga*100).toFixed(2) : null;

const pontCount = {adiantado:0,no_prazo:0,atrasado:0};
viagens.forEach(v=>{ if(v.pontualidade) pontCount[v.pontualidade] = (pontCount[v.pontualidade]||0)+1; });
const totalPont = pontCount.adiantado+pontCount.no_prazo+pontCount.atrasado;

// Agrupar rotas
const rotas = {};
viagens.forEach(v=>{
  if(!v.rota) return;
  if(!rotas[v.rota]) rotas[v.rota]={n:0,carga:0,custo:0};
  rotas[v.rota].n++; rotas[v.rota].carga+=parseFloat(v.valor_carga)||0; rotas[v.rota].custo+=parseFloat(v.custo_viagem)||0;
});
const rotasCrit = Object.entries(rotas)
  .map(([r,d])=>({rota:r,pct:d.carga>0?d.custo/d.carga*100:0}))
  .filter(r=>r.pct>=7).sort((a,b)=>b.pct-a.pct).slice(0,3);

// Montar texto do resumo (formato WhatsApp)
const semaforo = (val,meta) => val===null?'⚪':parseFloat(val)<meta?'🟢':parseFloat(val)<meta*1.3?'🟡':'🔴';
const fmtBRL = v => v>0 ? 'R$ '+v.toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:0}) : '—';
const fmtPct = v => v!==null ? v+'%' : '—';
const ptTxt = totalPont>0
  ? `✅ ${Math.round(pontCount.adiantado/totalPont*100)}% adiant. | 🟡 ${Math.round(pontCount.no_prazo/totalPont*100)}% prazo | 🔴 ${Math.round(pontCount.atrasado/totalPont*100)}% atraso`
  : 'Sem dados';
const linhasRotas = rotasCrit.length>0
  ? rotasCrit.map(r=>`   • ${r.rota}: ${r.pct.toFixed(1)}% ${r.pct<10?'⚠️':'🔴'}`).join('\n')
  : '   ✅ Todas dentro da meta';

const dataFmt = agora.toLocaleDateString('pt-BR');
const texto = [
  `📊 *LOGÍSTICA EM VIDROS — RESUMO SEMANAL*`,
  `_Semana ${seg.toLocaleDateString('pt-BR')} a ${dataFmt}_`,
  ``,
  `🚛 *VIAGENS*: ${viagens.length} viagem(ns)`,
  `   Carga: ${fmtBRL(totalCarga)} | Custo: ${fmtBRL(totalCusto)}`,
  `   ${semaforo(pctRota,7)} % Custo/Carga: *${fmtPct(pctRota)}* (meta < 7%)`,
  ``,
  `📍 *ROTAS ACIMA DA META:*`,
  linhasRotas,
  ``,
  `⏱️ *PONTUALIDADE*: ${ptTxt}`,
  `   Meta: ≤ 5% atraso`,
  ``,
  `🔧 *MANUTENÇÃO*: ${fmtBRL(totalManut)}`,
  `   ${semaforo(pctManut,2)} % Manut/Produção: *${fmtPct(pctManut)}* (meta < 2%)`,
  ``,
  `⛽ *ABASTECIMENTO*: ${fmtBRL(totalAbast)}`,
  ``,
  `📦 *QUEBRA EXPEDIÇÃO*: ${semaforo(pctQuebra,1)} ${fmtPct(pctQuebra)} (meta < 1%)`,
  ``,
  `_Gerado automaticamente — EM Vidros Logística_`,
].join('\n');

return [{
  json: {
    texto_resumo: texto,
    semana_inicio: seg.toISOString().split('T')[0],
    viagens_count: viagens.length,
    total_carga: totalCarga,
    total_custo: totalCusto,
    pct_custo_rota: pctRota,
    pct_quebra: pctQuebra,
    pct_manut_prod: pctManut
  }
}];
